META = dict(
    outline='ಶ್ಲೋಕಗಳು 1–6: ಶಾಸ್ತ್ರವಿಧಿಯಿಲ್ಲದೆ ಶ್ರದ್ಧೆಯಿಂದ ಪೂಜಿಸುವವರ ಗತಿ ಏನು? ಶ್ರದ್ಧೆ ಮೂರು ಬಗೆ; 7–10: ಮೂರು ಬಗೆಯ ಆಹಾರ; 11–13: ಮೂರು ಬಗೆಯ ಯಜ್ಞ; 14–19: ದೇಹ, ಮಾತು ಮತ್ತು ಮನಸ್ಸಿನ ತಪಸ್ಸು, ಮತ್ತು ಅದರಲ್ಲಿ ಮೂರು ಬಗೆ; 20–22: ಮೂರು ಬಗೆಯ ದಾನ; 23–28: "ಓಂ ತತ್ ಸತ್", ಮತ್ತು ಶ್ರದ್ಧೆಯಿಲ್ಲದೆ ಮಾಡಿದ್ದು ಏಕೆ ವ್ಯರ್ಥ.',
)
T = {
1: 'ಅರ್ಜುನ ಹೇಳಿದನು: ಹೇ ಕೃಷ್ಣ, ಶಾಸ್ತ್ರವಿಧಿಯನ್ನು ಬಿಟ್ಟು ಶ್ರದ್ಧೆಯಿಂದ ಪೂಜಿಸುವವರ ನಿಷ್ಠೆ ಯಾವುದು? ಅದು ಸತ್ತ್ವವೋ, ರಜಸ್ಸೋ, ತಮಸ್ಸೋ?',
2: 'ಶ್ರೀಭಗವಂತ ಹೇಳಿದನು: ದೇಹಧಾರಿಗಳ ಸ್ವಭಾವದಿಂದ ಹುಟ್ಟುವ ಶ್ರದ್ಧೆ ಮೂರು ಬಗೆ: ಸಾತ್ತ್ವಿಕ, ರಾಜಸಿಕ ಮತ್ತು ತಾಮಸಿಕ. ಅದರ ಬಗ್ಗೆ ಕೇಳು.',
4: 'ಸಾತ್ತ್ವಿಕರು ದೇವತೆಗಳನ್ನು ಪೂಜಿಸುತ್ತಾರೆ, ರಾಜಸಿಕರು ಯಕ್ಷರು ಮತ್ತು ರಾಕ್ಷಸರನ್ನು ಪೂಜಿಸುತ್ತಾರೆ. ಉಳಿದ ತಾಮಸಿಕರು ಪ್ರೇತಗಳು ಮತ್ತು ಭೂತಗಣಗಳನ್ನು ಪೂಜಿಸುತ್ತಾರೆ.',
5: 'ಶಾಸ್ತ್ರ ಹೇಳದ ಘೋರ ತಪಸ್ಸು ಮಾಡುವವರು, ದಂಭ ಮತ್ತು ಅಹಂಕಾರದಿಂದ ಕೂಡಿದವರು, ಕಾಮ, ಆಸಕ್ತಿ ಮತ್ತು ಬಲದ ಗರ್ವದಿಂದ ತುಂಬಿದವರು,',
6: 'ಅವಿವೇಕಿಗಳಾಗಿ ದೇಹದಲ್ಲಿರುವ ಭೂತಸಮೂಹವನ್ನೂ, ದೇಹದಲ್ಲಿರುವ ನನ್ನನ್ನೂ ಹಿಂಸಿಸುತ್ತಾರೆ. ಅವರನ್ನು ಆಸುರೀ ನಿಶ್ಚಯದವರೆಂದು ತಿಳಿ.',
7: 'ಎಲ್ಲರಿಗೂ ಇಷ್ಟವಾದ ಆಹಾರವೂ ಮೂರು ಬಗೆ, ಯಜ್ಞ, ತಪಸ್ಸು ಮತ್ತು ದಾನವೂ ಹಾಗೆಯೇ. ಅವುಗಳ ಈ ಭೇದವನ್ನು ಕೇಳು.',
8: 'ಆಯುಸ್ಸು, ಸತ್ತ್ವ, ಬಲ, ಆರೋಗ್ಯ, ಸುಖ ಮತ್ತು ಪ್ರೀತಿಯನ್ನು ಹೆಚ್ಚಿಸುವ, ರಸವತ್ತಾದ, ಜಿಡ್ಡುಳ್ಳ, ಸ್ಥಿರವಾದ ಮತ್ತು ಮನಸ್ಸಿಗೆ ಹಿತವಾದ ಆಹಾರಗಳು ಸಾತ್ತ್ವಿಕರಿಗೆ ಪ್ರಿಯ.',
9: 'ಕಹಿ, ಹುಳಿ, ಅತಿ ಉಪ್ಪು, ಅತಿ ಬಿಸಿ, ಖಾರ, ಒಣ ಮತ್ತು ಉರಿ ಉಂಟುಮಾಡುವ ಆಹಾರಗಳು ರಾಜಸಿಕರಿಗೆ ಪ್ರಿಯ; ಅವು ದುಃಖ, ಶೋಕ ಮತ್ತು ರೋಗವನ್ನು ತರುತ್ತವೆ.',
10: 'ಬಹಳ ಹೊತ್ತು ಇಟ್ಟಿದ್ದು, ರುಚಿ ಹೋದದ್ದು, ದುರ್ವಾಸನೆಯುಳ್ಳದ್ದು, ಹಳಸಿದ್ದು, ಎಂಜಲು ಮತ್ತು ಅಪವಿತ್ರವಾದ ಆಹಾರ ತಾಮಸಿಕರಿಗೆ ಪ್ರಿಯ.',
11: 'ಫಲವನ್ನು ಬಯಸದೆ, "ಇದನ್ನು ಮಾಡಲೇಬೇಕು" ಎಂದು ಮನಸ್ಸನ್ನು ನಿಲ್ಲಿಸಿ, ವಿಧಿಪೂರ್ವಕವಾಗಿ ಮಾಡುವ ಯಜ್ಞ ಸಾತ್ತ್ವಿಕ.',
12: 'ಆದರೆ ಹೇ ಭರತಶ್ರೇಷ್ಠ, ಫಲವನ್ನು ಬಯಸಿ, ಅಥವಾ ದಂಭಕ್ಕಾಗಿ ಮಾಡುವ ಯಜ್ಞವನ್ನು ರಾಜಸಿಕ ಎಂದು ತಿಳಿ.',
13: 'ವಿಧಿಯಿಲ್ಲದ, ಅನ್ನದಾನವಿಲ್ಲದ, ಮಂತ್ರವಿಲ್ಲದ, ದಕ್ಷಿಣೆಯಿಲ್ಲದ, ಶ್ರದ್ಧೆಯಿಲ್ಲದ ಯಜ್ಞವನ್ನು ತಾಮಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
14: 'ದೇವತೆಗಳು, ಬ್ರಾಹ್ಮಣರು, ಗುರುಗಳು ಮತ್ತು ಜ್ಞಾನಿಗಳ ಪೂಜೆ, ಶುಚಿತ್ವ, ಸರಳತೆ, ಬ್ರಹ್ಮಚರ್ಯ ಮತ್ತು ಅಹಿಂಸೆ: ಇದನ್ನು ದೇಹದ ತಪಸ್ಸು ಎನ್ನುತ್ತಾರೆ.',
16: 'ಮನಸ್ಸಿನ ಪ್ರಸನ್ನತೆ, ಸೌಮ್ಯತೆ, ಮೌನ, ಆತ್ಮಸಂಯಮ ಮತ್ತು ಭಾವಶುದ್ಧಿ: ಇದನ್ನು ಮನಸ್ಸಿನ ತಪಸ್ಸು ಎನ್ನುತ್ತಾರೆ.',
17: 'ಫಲವನ್ನು ಬಯಸದ, ಯೋಗದಲ್ಲಿ ನೆಲೆಸಿದ ಮನುಷ್ಯರು ಪರಮ ಶ್ರದ್ಧೆಯಿಂದ ಮಾಡುವ ಈ ಮೂರು ಬಗೆಯ ತಪಸ್ಸನ್ನು ಸಾತ್ತ್ವಿಕ ಎನ್ನುತ್ತಾರೆ.',
18: 'ಗೌರವ, ಮಾನ ಮತ್ತು ಪೂಜೆಯನ್ನು ಪಡೆಯಲು, ದಂಭದಿಂದ ಮಾಡುವ ತಪಸ್ಸು ರಾಜಸಿಕ; ಅದು ಚಂಚಲ ಮತ್ತು ಅಸ್ಥಿರ.',
19: 'ಮೂರ್ಖ ಹಠದಿಂದ, ತನ್ನನ್ನು ತಾನೇ ಹಿಂಸಿಸಿಕೊಂಡು, ಅಥವಾ ಇತರರನ್ನು ನಾಶಮಾಡಲು ಮಾಡುವ ತಪಸ್ಸನ್ನು ತಾಮಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
20: '"ಕೊಡುವುದು ನನ್ನ ಕರ್ತವ್ಯ" ಎಂದು ಭಾವಿಸಿ, ಪ್ರತ್ಯುಪಕಾರ ಮಾಡಲಾಗದವನಿಗೆ, ತಕ್ಕ ಸ್ಥಳದಲ್ಲಿ, ತಕ್ಕ ಸಮಯದಲ್ಲಿ, ತಕ್ಕ ವ್ಯಕ್ತಿಗೆ ಕೊಡುವ ದಾನ ಸಾತ್ತ್ವಿಕ.',
21: 'ಆದರೆ ಪ್ರತ್ಯುಪಕಾರಕ್ಕಾಗಿ, ಅಥವಾ ಫಲವನ್ನು ಬಯಸಿ, ಅಥವಾ ಕಷ್ಟಪಟ್ಟು ಕೊಡುವ ದಾನವನ್ನು ರಾಜಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
22: 'ತಕ್ಕದಲ್ಲದ ಸ್ಥಳದಲ್ಲಿ, ತಕ್ಕದಲ್ಲದ ಸಮಯದಲ್ಲಿ, ಅರ್ಹರಲ್ಲದವರಿಗೆ, ಗೌರವವಿಲ್ಲದೆ, ಅವಮಾನಿಸುತ್ತಾ ಕೊಡುವ ದಾನವನ್ನು ತಾಮಸಿಕ ಎನ್ನುತ್ತಾರೆ.',
23: '"ಓಂ ತತ್ ಸತ್": ಇದು ಬ್ರಹ್ಮದ ಮೂರು ಬಗೆಯ ಹೆಸರು. ಇದರಿಂದಲೇ ಹಿಂದೆ ಬ್ರಾಹ್ಮಣರು, ವೇದಗಳು ಮತ್ತು ಯಜ್ಞಗಳು ಸೃಷ್ಟಿಸಲ್ಪಟ್ಟವು.',
24: 'ಆದ್ದರಿಂದ ಬ್ರಹ್ಮವಾದಿಗಳು ಶಾಸ್ತ್ರವಿಧಿಯಲ್ಲಿ ಹೇಳಿದ ಯಜ್ಞ, ದಾನ ಮತ್ತು ತಪಸ್ಸಿನ ಕರ್ಮಗಳನ್ನು ಸದಾ "ಓಂ" ಎಂದು ಉಚ್ಚರಿಸಿ ಆರಂಭಿಸುತ್ತಾರೆ.',
25: 'ಮುಕ್ತಿಯನ್ನು ಬಯಸುವವರು ಫಲವನ್ನು ಬಯಸದೆ "ತತ್" ಎಂದು ಉಚ್ಚರಿಸಿ ಬಗೆಬಗೆಯ ಯಜ್ಞ, ತಪಸ್ಸು ಮತ್ತು ದಾನದ ಕರ್ಮಗಳನ್ನು ಮಾಡುತ್ತಾರೆ.',
26: 'ಹೇ ಪಾರ್ಥ, "ಸತ್" ಎಂಬ ಪದವನ್ನು ಸದ್ಭಾವದಲ್ಲೂ ಸಾಧುತ್ವದಲ್ಲೂ ಬಳಸುತ್ತಾರೆ; ಶುಭ ಕರ್ಮದಲ್ಲೂ "ಸತ್" ಎಂಬ ಪದ ಬಳಸಲ್ಪಡುತ್ತದೆ.',
27: 'ಯಜ್ಞ, ತಪಸ್ಸು ಮತ್ತು ದಾನದಲ್ಲಿನ ನಿಷ್ಠೆಯನ್ನೂ "ಸತ್" ಎನ್ನುತ್ತಾರೆ. ಅವುಗಳಿಗಾಗಿ ಮಾಡುವ ಕರ್ಮವನ್ನೂ "ಸತ್" ಎಂದೇ ಕರೆಯುತ್ತಾರೆ.',
28: 'ಹೇ ಪಾರ್ಥ, ಶ್ರದ್ಧೆಯಿಲ್ಲದೆ ಮಾಡುವ ಹೋಮ, ಕೊಡುವ ದಾನ, ಮಾಡುವ ತಪಸ್ಸು, ಮಾಡುವ ಯಾವುದೇ ಕರ್ಮವನ್ನು "ಅಸತ್" ಎನ್ನುತ್ತಾರೆ. ಅದು ಈ ಲೋಕದಲ್ಲೂ ಪರಲೋಕದಲ್ಲೂ ಪ್ರಯೋಜನವಿಲ್ಲ.',
}
